mapper.select:

        /* isry.regns.casemng.casereg.mapper.selectReqById - Lee.Myeong.Sang */
        SELECT A.CRISIS_SCRENN_RELM_SE_CD AS CRISIS_SCRENN_RELM_SE_CD,      /* 위기스크리닝영역구분코드 */
               A.CRISIS_SCRENN_EVL_SCORE AS CRISIS_SCRENN_EVL_SCORE,        /* 위기스크리닝평가점수 */
               A.CRISIS_SCRENN_RESULT_SE_CD AS CRISIS_SCRENN_RESULT_SE_CD,  /* 위기스크리닝결과구분코드 */

               A.CASE_MNG_NO AS CASE_MNG_NO,  /* 사례관리번호 */
               A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO  /* 사례관리차수 */
		 FROM ACA150 A
		WHERE CASE_MNG_NO = #{CASE_MNG_NO}
		  AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
          AND CRISIS_SCRENN_TRGT_SE_CD = #{CRISIS_SCRENN_TRGT_SE_CD}


        /* isry.regns.casemng.casereg.mapper.selectEfectnById - Lee.Myeong.Sang */
        SELECT A.EFECTN_RELM_SE_CD AS EFECTN_RELM_SE_CD,      /* 효과성영역구분코드 */
               A.EFECTN_EVL_SCORE AS EFECTN_EVL_SCORE,        /* 효과성평가점수 */

               A.CASE_MNG_NO AS CASE_MNG_NO,  /* 사례관리번호 */
               A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO  /* 사례관리차수 */
		 FROM ACA180 A
		WHERE CASE_MNG_NO = #{CASE_MNG_NO}
		  AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
          AND CASE_PRGRS_STTS_SE_CD = #{CASE_PRGRS_STTS_SE_CD}
